# Reference values from OrdinaryDiffEqTaylorSeries, generated by
# tools/taylor-probe.jl (see its header for the ChainRules patch the Julia
# environment needs): saved points, f evaluations, rejections, accepted
# steps and the final state.

taylort_lv <- function(u, p, t) c(p[1] * u[1] - u[1] * u[2], -p[2] * u[2] + u[1] * u[2])
taylort_lvprob <- ODEProblem(taylort_lv, c(1, 1), c(0, 2), c(1.5, 3))
taylort_osc <- function(u, p, t) c(u[2], -u[1] + p[1] * t * t / (1 + t))
taylort_oscprob <- ODEProblem(taylort_osc, c(1, 0), c(0, 3), 0.5)
taylort_cb <- function() DiscreteCallback(function(u, t, integ) t == 1, function(integ) integ$u <- integ$u * 0.5)

taylort_check <- function(sol, stats, u) {
  st <- sol$stats
  expect_identical(c(length(sol$t), st$nf, st$nreject, st$naccept), as.integer(stats))
  expect_equal(sol$u[[length(sol$u)]], u, tolerance = 1e-10)
}

test_that("ExplicitTaylor2 matches OrdinaryDiffEqTaylorSeries", {
  taylort_check(solve(taylort_lvprob, ExplicitTaylor2(), dt = 0.01),
                c(201, 600, 0, 200), c(6.779076621111822, 2.012141071050593))
  taylort_check(solve(taylort_oscprob, ExplicitTaylor2(), dt = 0.01),
                c(301, 900, 0, 300), c(-0.10910557013657105, 0.6324193677127128))
  taylort_check(solve(taylort_lvprob, ExplicitTaylor2(), dt = 0.01, tstops = 1, callback = taylort_cb()),
                c(202, 601, 0, 200), c(5.653491512192999, 0.13418428125924192))
})

test_that("ExplicitTaylor matches OrdinaryDiffEqTaylorSeries", {
  tol <- function(prob, P) solve(prob, ExplicitTaylor(order = P), reltol = 1e-8, abstol = 1e-10)
  taylort_check(tol(taylort_lvprob, 2), c(1547, 4640, 0, 1546), c(6.77721049034804, 2.0127441474166683))
  taylort_check(tol(taylort_oscprob, 2), c(1930, 5789, 0, 1929), c(-0.10910842915871728, 0.6323577178253896))
  taylort_check(tol(taylort_lvprob, 4), c(124, 617, 0, 123), c(6.777188926244254, 2.0127543232290592))
  taylort_check(tol(taylort_oscprob, 4), c(114, 567, 0, 113), c(-0.10910849128351824, 0.6323558239437935))
  taylort_check(tol(taylort_lvprob, 8), c(24, 209, 0, 23), c(6.777189379134409, 2.0127536861154325))
  taylort_check(tol(taylort_oscprob, 8), c(21, 182, 0, 20), c(-0.10910848218232354, 0.6323558436122904))
  taylort_check(solve(taylort_lvprob, ExplicitTaylor(order = 4), reltol = 1e-8, abstol = 1e-10, tstops = 1,
                      callback = taylort_cb()),
                c(117, 577, 0, 115), c(5.653932666025566, 0.1342327261150487))
  taylort_check(solve(taylort_lvprob, ExplicitTaylor(order = 4), dt = 0.05, adaptive = FALSE),
                c(41, 200, 0, 40), c(6.777101871535449, 2.01286231877979))
})

test_that("ExplicitTaylorAdaptiveOrder matches OrdinaryDiffEqTaylorSeries", {
  taylort_check(solve(taylort_lvprob, ExplicitTaylorAdaptiveOrder(), reltol = 1e-8, abstol = 1e-10),
                c(100, 1140, 68, 99), c(6.777189388137977, 2.012753712005422))
  taylort_check(solve(taylort_oscprob, ExplicitTaylorAdaptiveOrder(), reltol = 1e-8, abstol = 1e-10),
                c(65, 764, 49, 64), c(-0.10910848212708453, 0.6323558437181002))
  taylort_check(solve(taylort_lvprob, ExplicitTaylorAdaptiveOrder(), reltol = 1e-8, abstol = 1e-10, tstops = 1,
                      callback = taylort_cb()),
                c(95, 1029, 65, 93), c(5.653932562134847, 0.13423274628273893))
  taylort_check(solve(taylort_lvprob, ExplicitTaylorAdaptiveOrder(min_order = 4, max_order = 9),
                      reltol = 1e-12, abstol = 1e-12),
                c(74, 730, 8, 73), c(6.77718938828024, 2.0127537115647685))
  taylort_check(solve(taylort_oscprob, ExplicitTaylorAdaptiveOrder(min_order = 2, max_order = 5),
                      reltol = 1e-6, abstol = 1e-8),
                c(75, 377, 1, 74), c(-0.10910848228723129, 0.632355843256515))
})

test_that("the Taylor dense output matches OrdinaryDiffEqTaylorSeries", {
  dense <- function(sol, t, u) expect_equal(as.numeric(sol(t)), u, tolerance = 1e-12)
  dense(solve(taylort_lvprob, ExplicitTaylor2(), dt = 0.01), 1.234, c(3.705577187312291, 0.27222962515447857))
  dense(solve(taylort_lvprob, ExplicitTaylor(order = 4), reltol = 1e-8, abstol = 1e-10), 0.373,
        c(1.3405669216594291, 0.5005053373554065))
  dense(solve(taylort_oscprob, ExplicitTaylor(order = 4), reltol = 1e-8, abstol = 1e-10), 2.345,
        c(-0.2602692022188502, -0.15408970270218678))
  dense(solve(taylort_oscprob, ExplicitTaylorAdaptiveOrder(), reltol = 1e-8, abstol = 1e-10), 2.345,
        c(-0.2602692051173539, -0.15408968449407803))
})

test_that("Taylor methods reject unsupported input", {
  expect_error(ExplicitTaylor(order = 0), "positive integer")
  expect_error(solve(ODEProblem(function(u, p, t) sin(u) * abs(u), 1, c(0, 1)), ExplicitTaylor(order = 3),
                     reltol = 1e-6), "abs")
})
